insert into events (id, title, category, themes, age_min, age_max, age_label, price, cost, level, format, event_date, deadline_date, place, short_desc, description, instagram, registration_url, is_past)
values
('e1', 'Городская уборка парка Ататюрк', 'volunteering', '{eco}', 13, 18, '13–18 лет', 'free', null, 'local', 'Личное', '2026-09-06', '2026-09-03', 'Парк Ататюрк, Бишкек', 'Субботник с эко-клубом: перчатки, мешки и хорошая музыка от нас.', 'Собираем 60 подростков на утреннюю уборку парка. Инвентарь и вода — от организаторов, сертификат волонтёра — каждому участнику. После уборки короткий пикник и знакомство с эко-клубом.', 'https://instagram.com/teenagespace_demo', 'https://example.org/register', false),
('e2', 'Хакатон Bishkek AI Weekend', 'hackathon', '{it}', 15, 21, '15–21 лет', 'free', null, 'local', 'Командное', '2026-09-19', '2026-09-12', 'Ololo Hub, Бишкек', '48 часов, команды по 4 человека, менторы из локальных IT-компаний.', 'Два дня на прототип с использованием AI. Треки: образование, город, экология. Менторы помогают с идеей и питчем, финалистов ждёт стажировка.', 'https://instagram.com/teenagespace_demo', 'https://example.org/register', false),
('e3', 'Республиканская олимпиада по математике', 'olympiad', '{it}', 14, 18, '14–18 лет', 'free', null, 'local', 'Личное', '2026-10-11', '2026-10-01', 'КНУ, Бишкек', 'Отборочный тур, победители едут на международный этап.', 'Два тура: письменный отбор и финал. Победители получают приглашение на международный этап и рекомендации для поступления.', null, 'https://example.org/register', false),
('e4', 'Модель ООН Central Asia MUN', 'eduevent', '{mun}', 15, 18, '15–18 лет', 'paid', '1 200 сом', 'intl', 'Личное', '2026-11-01', '2026-10-20', 'AUCA, Бишкек', 'Три дня дебатов на английском, делегаты из пяти стран.', 'Комитеты по безопасности, климату и правам человека. Рабочий язык — английский. Для новичков есть подготовительный воркшоп за неделю до конференции.', 'https://instagram.com/teenagespace_demo', 'https://example.org/register', false),
('e5', 'Конкурс короткого метра «Мой Бишкек»', 'contest', '{media}', 13, 18, '13–18 лет', 'free', null, 'local', 'Командное', '2026-09-28', '2026-09-20', 'Онлайн + показ в кинотеатре', 'Снимите фильм до 5 минут о своём районе.', 'Принимаются работы до 5 минут, снятые на любую камеру, включая телефон. Лучшие фильмы покажут на большом экране, авторы получат менторство от режиссёров.', 'https://instagram.com/teenagespace_demo', 'https://example.org/register', false),
('e6', 'Школа социальных проектов', 'social', '{eco,media}', 14, 18, '14–18 лет', 'free', null, 'local', 'Командное', '2026-10-04', '2026-09-25', 'Библиотека им. Баялинова', 'Шесть занятий: от идеи до заявки на грант.', 'Программа для тех, кто хочет запустить свой проект: поиск проблемы, работа с командой, бюджет, презентация. Финал — защита перед донорами.', null, 'https://example.org/register', false),
('e7', 'Турнир по стритболу 3x3', 'other', '{sport}', 14, 17, '14–17 лет', 'paid', '300 сом с команды', 'local', 'Командное', '2026-09-13', '2026-09-10', 'Спортплощадка, мкр Джал', 'Команды по 3 игрока, групповой этап и плей-офф в один день.', 'Регистрация команд до 10 сентября. Групповой этап утром, плей-офф после обеда. Победителям — мячи и форма от партнёров.', 'https://instagram.com/teenagespace_demo', 'https://example.org/register', false),
('e8', 'Международный конкурс эссе Global Voices', 'contest', '{media,mun}', 16, 18, '16–18 лет', 'free', null, 'intl', 'Личное', '2026-11-15', '2026-10-30', 'Онлайн', 'Эссе на английском, финалисты выступают на онлайн-форуме.', 'Тема года — «Молодёжь и климат». Объём до 1000 слов. Пятнадцать финалистов приглашаются на онлайн-форум и получают сертификаты.', null, 'https://example.org/register', false),
('e9', 'Воркшоп по цифровой безопасности', 'eduevent', '{it}', 13, 18, '13–18 лет', 'free', null, 'local', 'Личное', '2026-09-24', null, 'Ololo Hub, Бишкек', 'Пароли, фишинг, приватность — на практике за два часа.', 'Практический воркшоп: как защитить аккаунты, распознать фишинг и настроить приватность в соцсетях. Свой ноутбук приветствуется.', 'https://instagram.com/teenagespace_demo', null, false),
('e10', 'Помощь приюту для животных', 'volunteering', '{eco}', 15, 21, '15–21 лет', 'free', null, 'local', 'Личное', '2026-09-08', null, 'Приют «Добрые руки»', 'Выгул, уборка вольеров, помощь на фотосессии для объявлений.', 'Смена на 4 часа. Нужна закрытая обувь и одежда, которую не жалко. Волонтёрские часы подтверждаем справкой.', 'https://instagram.com/teenagespace_demo', 'https://example.org/register', false),
('e11', 'Летняя эко-экспедиция Ala-Archa', 'volunteering', '{eco,sport}', 16, 18, '16–18 лет', 'paid', '2 500 сом', 'local', 'Командное', '2026-08-02', null, 'Ала-Арча', 'Три дня в горах: маркировка троп и сбор мусора.', 'Палаточный лагерь, работа с рейнджерами парка, вечерние лекции об экологии гор. Снаряжение частично предоставляется.', 'https://instagram.com/teenagespace_demo', null, true),
('e12', 'Хакатон EdTech Spring', 'hackathon', '{it,media}', 15, 18, '15–18 лет', 'free', null, 'local', 'Командное', '2026-07-19', null, 'AUCA, Бишкек', 'Прототипы для школ: 24 часа и защита перед учителями.', 'Участники делали инструменты для школьных задач. Победители внедрили проект в двух школах Бишкека.', 'https://instagram.com/teenagespace_demo', null, true),
('e13', 'Медиа-лагерь «Голос поколения»', 'eduevent', '{media}', 14, 17, '14–17 лет', 'paid', '1 800 сом', 'local', 'Личное', '2026-06-28', null, 'Иссык-Куль', 'Пять дней: съёмка, монтаж, подкасты, публичная речь.', 'Интенсив от журналистов и видеографов. Каждый участник выпустил свой материал в итоговом альманахе лагеря.', null, null, true),
('e14', 'Олимпиада по биологии, городской этап', 'olympiad', '{eco}', 14, 18, '14–18 лет', 'free', null, 'local', 'Личное', '2026-05-17', null, 'Школа №61, Бишкек', 'Теория и практикум с микроскопом.', 'Городской этап включал письменный тур и лабораторный практикум. Победители прошли на республиканский этап.', null, null, true)
on conflict (id) do update set
  title = excluded.title, category = excluded.category, themes = excluded.themes,
  age_min = excluded.age_min, age_max = excluded.age_max, age_label = excluded.age_label,
  price = excluded.price, cost = excluded.cost, level = excluded.level, format = excluded.format,
  event_date = excluded.event_date, deadline_date = excluded.deadline_date, place = excluded.place,
  short_desc = excluded.short_desc, description = excluded.description, instagram = excluded.instagram,
  registration_url = excluded.registration_url, is_past = excluded.is_past;

