insert into education_tracks (id, title, intro, sort_order) values
('nct', 'Подготовка к НЦТ/ОРТ', 'Материалы, разборы и расписание бесплатных занятий по НЦТ/ОРТ', 0),
('abroad', 'Подготовка к поступлению за границу', 'Как поступать за границу: сроки, документы, стипендии', 1)
