insert into materials (id, track, title, meta, body, sort_order) values
('m1', 'nct', 'С чего начать подготовку к НЦТ за год', 'разбор · 8 мин', ARRAY[
  'НЦТ проверяет не память, а скорость мышления. Первое, что стоит сделать — пройти пробный тест целиком и без подготовки, чтобы увидеть реальную стартовую точку.',
  'Дальше работает простая схема: два блока по 40 минут в день, один на математику, второй на аналогии и чтение. Раз в две недели — полный пробник по времени.',
  'Ошибки важнее правильных ответов. Ведите таблицу типов ошибок: невнимательность, незнание темы, нехватка времени. Через месяц станет видно, куда уходят баллы.'
], 1),
('m2', 'nct', 'Математический блок: 12 тем, которые дают больше всего баллов', 'конспект · 12 мин', ARRAY[
  'Проценты, пропорции, движение, работа, площади, степени — эти темы встречаются в каждом варианте.',
  'Разбирайте не задачу, а тип задачи. Когда узнаёте тип за пять секунд, экономите минуту на каждом вопросе.'
], 2),
('m3', 'nct', 'Расписание бесплатных пробников в Бишкеке', 'обновляется · 3 мин', ARRAY[
  'Пробники проводят несколько центров и школ; ниже — календарь на ближайший месяц.',
  'Записываться стоит заранее: места на бесплатные потоки заканчиваются за неделю.'
], 3),
('m4', 'abroad', 'Календарь поступления: за 18 месяцев до дедлайна', 'гайд · 10 мин', ARRAY[
  'Поступление за границу — это проект с дедлайнами. Первый год уходит на язык и внеучебную активность, последние шесть месяцев — на документы и эссе.',
  'Начните с языкового теста: IELTS или TOEFL дают понимание, сколько времени нужно на подготовку остального.'
], 1),
('m5', 'abroad', 'Мотивационное эссе: структура, которая работает', 'разбор · 9 мин', ARRAY[
  'Хорошее эссе отвечает на три вопроса: что вы сделали, что поняли и зачем вам эта программа.',
  'Избегайте общих фраз о «стремлении к знаниям». Один конкретный случай убеждает сильнее десяти обещаний.'
], 2),
('m6', 'abroad', 'Стипендии, доступные школьникам из Кыргызстана', 'список · 6 мин', ARRAY[
  'Есть программы полного финансирования и частичные гранты; требования к среднему балу и языку различаются.',
  'Собирайте документы на самую раннюю дату дедлайна из вашего списка — почти все требуют одинаковый набор.'
], 3)
on conflict (id) do update set track = excluded.track, title = excluded.title, meta = excluded.meta, body = excluded.body, sort_order = excluded.sort_order;
